module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam AW = $clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [AW:0] wptr, rptr;

  wire do_wr = wr_en && !full;
  wire do_rd = rd_en && !empty;

  assign full  = (wptr[AW] != rptr[AW]) && (wptr[AW-1:0] == rptr[AW-1:0]);
  assign empty = (wptr == rptr);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wptr <= {(AW+1){1'b0}};
    end else if (do_wr) begin
      mem[wptr[AW-1:0]] <= din;
      wptr <= wptr + {{AW{1'b0}}, 1'b1};
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rptr <= {(AW+1){1'b0}};
      dout <= {WIDTH{1'b0}};
    end else if (do_rd) begin
      dout <= mem[rptr[AW-1:0]];
      rptr <= rptr + {{AW{1'b0}}, 1'b1};
    end
  end

endmodule
